main_tf = """
provider "aws" {
  region = var.region
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.lambda_name}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{ Action = "sts:AssumeRole", Effect = "Allow", Principal = { Service = "lambda.amazonaws.com" } }]
  })
}

resource "aws_iam_role_policy" "lambda_policy" {
  role = aws_iam_role.lambda_exec.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Action = ["ses:SendTemplatedEmail"], Effect = "Allow", Resource = "*" },
      { Action = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"], Effect = "Allow", Resource = "arn:aws:logs:*:*:*" }
    ]
  })
}

resource "aws_lambda_function" "contact_handler" {
  filename      = "exports.zip"
  function_name = var.lambda_name
  role          = aws_iam_role.lambda_exec.arn
  handler       = "exports.handler"
  runtime       = "nodejs18.x"
  environment {
    variables = {
      SES_TEMPLATE_NAME = "ContactFormTemplate"
      PRIMARY_RECIPIENT   = var.primary_recipient
      ADMIN_RECIPIENT     = var.admin_recipient
      CAPTCHA_SECRET      = var.captcha_secret
    }
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name = "contact-form-api"
}

resource "aws_api_gateway_resource" "contact" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "contact-us"
}

resource "aws_api_gateway_method" "post" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.contact.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "lambda" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.contact.id
