  type        = "AWS_PROXY"
  integration_http_method = "POST"
  uri         = aws_lambda_function.contact_handler.invoke_arn
}

resource "aws_api_gateway_deployment" "v1" {
  depends_on  = [aws_api_gateway_integration.lambda]
