exports_js = """
const { SESClient, SendTemplatedEmailCommand } = require("@aws-sdk/client-ses");
const https = require("https");

const ses = new SESClient({ region: process.env.AWS_REGION });

exports.handler = async (event) => {
    const body = JSON.parse(event.body);
    const { firstName, lastName, email, subject, message, captchaToken } = body;

    if (!firstName || !lastName || !email || !subject || !message || !captchaToken) {
        return { statusCode: 400, body: JSON.stringify({ error: "Missing required fields" }) };
    }

    const isCaptchaValid = await verifyCaptcha(captchaToken);
    if (!isCaptchaValid) {
        return { statusCode: 400, body: JSON.stringify({ error: "Invalid captcha" }) };
    }

    try {
        await ses.send(new SendTemplatedEmailCommand({
            Source: "noreply@yourdomain.com",
            Destination: { ToAddresses: [process.env.PRIMARY_RECIPIENT, process.env.ADMIN_RECIPIENT] },
            Template: process.env.SES_TEMPLATE_NAME,
            TemplateData: JSON.stringify({ firstName, lastName, email, subject, message })
        }));
        return { statusCode: 200, body: JSON.stringify({ message: "Success" }) };
    } catch (err) {
        return { statusCode: 500, body: JSON.stringify({ error: "Internal Server Error" }) };
    }
};

function verifyCaptcha(token) {
    return new Promise((resolve) => {
        const data = `secret=${process.env.CAPTCHA_SECRET}&response=${token}`;
        const options = {
            hostname: "www.google.com",
            path: "/recaptcha/api/siteverify",
            method: "POST",
            headers: { "Content-Type": "application/x-www-form-urlencoded" }
        };
        const req = https.request(options, (res) => {
            let d = "";
            res.on("data", (c) => d += c);
            res.on("end", () => resolve(JSON.parse(d).success));
        });
        req.write(data);
        req.end();
    });
}
"""

